PAGE_TEMPLATE = r"""<!doctype html>
<html lang="vi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Rạng Đông Key Helper</title>
<style nonce="__NONCE__">
:root{color-scheme:light dark;font-family:system-ui,sans-serif}body{margin:0;background:light-dark(#f4f7f4,#141c1b);color:light-dark(#20382e,#edf6f0)}main{max-width:780px;margin:auto;padding:24px}section{padding:22px;margin:20px 0;border:1px solid #78908160;border-radius:14px;background:light-dark(white,#202e28)}label{display:block;margin:16px 0}input{display:block;width:100%;box-sizing:border-box;padding:12px;margin-top:8px;border:1px solid #789081;border-radius:7px;font:inherit;background:transparent;color:inherit}button,a.button{display:inline-block;background:#197b55;color:white;border:0;border-radius:8px;padding:12px 18px;font:inherit;margin:8px 8px 8px 0;cursor:pointer;text-decoration:none}button:disabled{opacity:.55;cursor:wait}.secondary{background:light-dark(#e5eee8,#354c40);color:inherit}.small{font-size:14px;opacity:.8;line-height:1.6}#message{padding:14px;overflow-wrap:anywhere}.error{color:light-dark(#b52b31,#ffb3b6)}table{width:100%;border-collapse:collapse;font-size:14px}th,td{padding:12px 8px;border-bottom:1px solid #78908160;text-align:left;overflow-wrap:anywhere}.scroll{overflow:auto}summary{cursor:pointer}h1{font-size:29px}[hidden]{display:none!important}
</style></head><body><main>
<h1>Rạng Đông Key Helper</h1><p class="small">Đăng nhập một lần để chuyển local key vào Home Assistant.</p>
<section><h2>License</h2><p id="licenseStatus">Đang kiểm tra…</p><a id="buyLink" class="button" target="_blank" rel="noopener noreferrer" hidden>Nhận dùng thử / mua / xem key</a>
<details id="licenseDetails"><summary>Nhập hoặc đổi License Key</summary><label>License Key<input id="licenseKey" type="password" autocomplete="off" maxlength="128"></label><button id="activate">Kích hoạt</button></details></section>
<section><h2>Tài khoản Rạng Đông</h2><label>Email Rạng Đông<input id="account" autocomplete="off" spellcheck="false"></label><label>Mật khẩu Rạng Đông<input id="password" type="password" autocomplete="off"></label><p class="small">Dùng mật khẩu Rạng Đông, không phải mật khẩu email. Không lưu mật khẩu đăng nhập.</p><button id="login">Đăng nhập và lấy key</button></section>
<p id="message" role="status" aria-live="polite">Sẵn sàng.</p>
<section><h2>Thiết bị đã lấy key</h2><p id="empty" class="small">Chưa có thiết bị trong lần chạy này.</p><div class="scroll"><table id="devices" hidden><thead><tr><th>Tên</th><th>Device ID</th><th>IP</th><th>Key</th></tr></thead><tbody id="rows"></tbody></table></div><button id="clear" class="secondary">Xóa key tạm khỏi bridge</button><p class="small">Thêm tích hợp → Rạng Đông Smart → nhập Device ID, IP và local key thủ công. Home Assistant cần truy cập được LAN thiết bị.</p></section>
</main><script nonce="__NONCE__">
"use strict";
const csrfToken = __CSRF_JSON__;
const base = window.location.pathname.endsWith("/") ? window.location.pathname : `${window.location.pathname}/`;
const el = Object.fromEntries(["licenseStatus","licenseKey","licenseDetails","buyLink","activate","account","password","login","message","empty","devices","rows","clear"].map(id=>[id,document.getElementById(id)]));
let permitted = false;
let working = false;
let expiryTimer;
function lock(){permitted=false;devices([]);el.account.disabled=true;el.password.disabled=true;busy(working);}
function busy(value){working=value;document.querySelectorAll("button").forEach(button=>button.disabled=value);el.login.disabled=value||!permitted;el.account.disabled=value||!permitted;el.password.disabled=value||!permitted;}
function message(text,error=false){el.message.textContent=text;el.message.classList.toggle("error",error);}
async function api(path,body,method){const response=await fetch(`${base}api/${path}`,{method:method||(body===undefined?"GET":"POST"),headers:{"Content-Type":"application/json","X-CSRF-Token":csrfToken},body:body===undefined?undefined:JSON.stringify(body),cache:"no-store"});const result=await response.json();if(response.status===403&&result.error==="license_required")lock();if(!response.ok||result.success===false)throw new Error(result.message||"Không thực hiện được yêu cầu.");return result;}
function license(data){clearTimeout(expiryTimer);permitted=data.valid===true&&data.enforced===true&&data.status==="active"&&Number.isFinite(data.expires_at)&&data.expires_at*1000>Date.now();if(permitted){expiryTimer=setTimeout(()=>{lock();el.licenseStatus.textContent="Xác nhận license đã hết hạn. Hãy gia hạn hoặc mua gói vĩnh viễn, rồi kiểm tra lại.";refreshLicense().catch(()=>{});},Math.min(data.expires_at*1000-Date.now(),2147483647));}else{lock();}const texts={active:"License đang hoạt động.",compatibility:"Bản tương thích: chủ dự án chưa bật yêu cầu license.",license_required:"Chưa có license. Đăng ký website, nhận thử 1 ngày hoặc mua key rồi nhập vào đây.",offline_grace:"Server tạm thời không liên lạc được. Đang dùng xác nhận đã ký còn hạn.",server_unavailable:"Chưa kết nối được server license.",server_not_configured:"Chủ dự án chưa cấu hình server license.",license_bound:"Key đã gắn với Home Assistant khác. Liên hệ admin để reset.",component_bound:"Suất add-on đã được kích hoạt ở bản cài khác.",trial_already_used:"Home Assistant này đã dùng thử. Đổi tài khoản không được nhận thêm lượt; hãy chọn gói trả phí.",retry_later:"Chờ 60 giây trước khi kiểm tra lại.",license_invalid:"License đã hết hạn, bị khóa, thu hồi hoặc không đúng."};el.licenseStatus.textContent=texts[data.status]||"License chưa hợp lệ.";el.licenseDetails.open=!permitted;el.buyLink.hidden=true;if(data.buy_url){try{const url=new URL(data.buy_url);if(url.protocol==="https:"){el.buyLink.href=url.href;el.buyLink.hidden=false;}}catch{}}busy(working);}
function devices(records){el.rows.replaceChildren();if(!permitted)records=[];for(const record of records||[]){const row=document.createElement("tr");for(const field of ["name","device_id","host","local_key"]){const value=record[field];const cell=document.createElement("td");const text=document.createElement("span");text.textContent=value||"—";cell.append(text);if(value&&field!=="name"){const copy=document.createElement("button");copy.type="button";copy.className="secondary";copy.textContent="Sao chép";copy.addEventListener("click",async()=>{try{const status=await refreshLicense();if(!status.valid)return;await navigator.clipboard.writeText(value);message("Đã sao chép đầy đủ.");}catch{message("Không thể sao chép tự động. Hãy chọn và sao chép toàn bộ giá trị hiển thị.",true);}});cell.append(copy);}row.append(cell);}el.rows.append(row);}el.devices.hidden=!el.rows.children.length;el.empty.hidden=!!el.rows.children.length;}
async function refreshLicense(){try{const result=await api("license");license(result);return result;}catch(error){lock();el.licenseStatus.textContent="Không xác minh được license. Chức năng lấy/xem key đang khóa; hãy kiểm tra kết nối và thử lại.";throw error;}}
async function run(work){busy(true);try{await work();}catch(error){message(error.message,true);}finally{el.password.value="";el.licenseKey.value="";busy(false);}}
el.activate.addEventListener("click",()=>{const payload={key:el.licenseKey.value};el.licenseKey.value="";run(async()=>{try{const result=await api("license",payload);license(result);message(result.valid?"Đã kích hoạt license.":"License chưa hợp lệ.",!result.valid);}finally{payload.key="";}});});
el.login.addEventListener("click",()=>{const payload={username:el.account.value.trim(),password:el.password.value,country_code:"84"};el.password.value="";run(async()=>{message("Đang đăng nhập và lấy key…");try{const result=await api("cloud/login-scan",payload);devices(result.devices);message(result.message||"Đã chuyển key vào Home Assistant.");}finally{payload.password="";}});});
el.clear.addEventListener("click",()=>run(async()=>{const result=await api("bridge",undefined,"DELETE");devices([]);message(result.message||"Đã xóa key tạm.");}));
busy(true);refreshLicense().then(async result=>{if(result.valid)devices((await api("status")).devices);}).catch(error=>message(error.message,true)).finally(()=>busy(false));
setInterval(()=>refreshLicense().catch(()=>{}),30000);
document.addEventListener("visibilitychange",()=>{if(!document.hidden)refreshLicense().catch(()=>{});});
</script></body></html>"""
